    'dec.sharedNote': 'Các giếng cùng mỏ dùng chung nhu cầu nhiệt/điện của giàn và một lần vốn kết nối: tính riêng từng giếng sẽ ra {a} tỷ đ (đếm trùng), kế hoạch tối ưu cả mỏ là {b} tỷ đ.', 'dec.evpiNote': 'Tổng giá trị đo thêm: {v} tỷ đ.', 'b.decide': 'Quyết định giếng', 'doc.decide': 'Quyết định cho từng giếng', 'exp.decide': 'Quyet dinh',
